function renderLanding(){
  const items=db.dishes.filter(d=>d.active&&(menuType==="drink"?d.sec==="hotpot"||d.name.startsWith("Lẩu"):d.cat==="food"&&d.sec!=="hotpot"&&!d.name.startsWith("Lẩu"))).sort((a,b)=>((b.sig?2:0)+(b.img?1:0))-((a.sig?2:0)+(a.img?1:0))).slice(0,4);
  $("menuItems").innerHTML=items.length?items.map(m=>`<article class="menu-card">${(a=>`<div class="thumb${a.cls}" style="${a.style}" role="img" aria-label="${esc(m.name)}">${a.txt}</div>`)(art(m,m.cat==='drink'))}<div><h3>${esc(m.name)}</h3><p>${esc(m.desc)}</p>${m.vi?`<p class="dvi">${esc(m.vi)}</p>`:""}<span class="price num">${priceText(m)}</span></div></article>`).join(""):`<div class="l-empty">${t("emptyMenu")}</div>`;
  const rooms=db.rooms.filter(r=>r.active).sort((a,b)=>a.price-b.price);
  if($("roomItems"))$("roomItems").innerHTML=rooms.length?rooms.slice(0,3).map(r=>`<article class="room-card">${(a=>`<a href="#karaoke" class="thumb${a.cls}" style="${a.style}" aria-label="${esc(r.name)}">${a.txt}</a>`)(art(r,r.kind==='vip'))}<div class="room-body"><div class="room-top"><h3>${esc(r.name)}</h3></div><p>${esc(r.desc)}</p><div class="room-meta"><span>Ảnh minh hoạ</span><span class="price num">${vnd(r.price)}<small>${t("perHour")}</small></span></div></div></article>`).join(""):`<div class="l-empty">${t("emptyRooms")}</div>`;
  if($("bookingType")){const cur=$("bookingType").value;
  $("bookingType").innerHTML=`<option value="Nhà hàng">${t("restaurantOpt")}</option>`+rooms.map(r=>`<option value="Karaoke ${esc(r.name)}">Karaoke · ${esc(r.name)} · ${vnd(r.price)}${t("perHour")}</option>`).join("")+`<option value="Nhà hàng + Karaoke">${t("restaurantOpt")} + Karaoke</option>`;
  if([...$("bookingType").options].some(o=>o.value===cur))$("bookingType").value=cur;}
}
